{"path": "/tmp/sv-8f52cced0b7349b2ae8e5fbc3bd96c5c/RecipeCommunity/Services/RecipeService.cs", "file_text": "using RecipeCommunity.Models;

namespace RecipeCommunity.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes = new()
    {
        new Recipe { Id = 1, Title = "Classic Margherita Pizza", Category = "Italian", Ingredients = "Pizza dough\nSan Marzano tomatoes\nFresh mozzarella\nFresh basil\nOlive oil\nSalt", Steps = "1. Preheat oven to 475°F.\n2. Roll out dough on a floured surface.\n3. Spread crushed tomatoes evenly.\n4. Tear mozzarella and distribute over sauce.\n5. Bake for 10-12 minutes until crust is golden.\n6. Top with fresh basil and drizzle with olive oil.", AverageRating = 4.5, RatingCount = 12 },
        new Recipe { Id = 2, Title = "Chicken Tikka Masala", Category = "Indian", Ingredients = "Chicken breast\nYogurt\nGaram masala\nTurmeric\nCumin\nTomato sauce\nHeavy cream\nGarlic\nGinger\nOnion", Steps = "1. Marinate chicken in yogurt and spices for 2 hours.\n2. Grill or broil chicken until charred.\n3. Sauté onion, garlic, and ginger.\n4. Add tomato sauce and spices, simmer 15 minutes.\n5. Add cream and cooked chicken.\n6. Simmer 10 more minutes. Serve with rice.", AverageRating = 4.8, RatingCount = 25 },
        new Recipe { Id = 3, Title = "Beef Tacos", Category = "Mexican", Ingredients = "Ground beef\nTaco seasoning\nCorn tortillas\nLettuce\nTomato\nCheddar cheese\nSour cream\nSalsa", Steps = "1. Brown ground beef in a skillet.\n2. Add taco seasoning and water, simmer 5 minutes.\n3. Warm tortillas in a dry pan.\n4. Assemble tacos with beef and toppings.\n5. Serve with salsa and sour cream.", AverageRating = 4.2, RatingCount = 8 },
        new Recipe { Id = 4, Title = "Pad Thai", Category = "Asian", Ingredients = "Rice noodles\nShrimp or tofu\nEggs\nBean sprouts\nGreen onions\nPeanuts\nLime\nFish sauce\nTamarind paste\nSugar", Steps = "1. Soak rice noodles in warm water for 30 minutes.\n2. Stir-fry shrimp or tofu until cooked.\n3. Push aside, scramble eggs in the pan.\n4. Add drained noodles and sauce mixture.\n5. Toss with bean sprouts and green onions.\n6. Serve with crushed peanuts and lime wedges.", AverageRating = 4.6, RatingCount = 18 },
        new Recipe { Id = 5, Title = "Chocolate Lava Cake", Category = "Desserts", Ingredients = "Dark chocolate\nButter\nEggs\nSugar\nFlour\nVanilla extract\nPowdered sugar", Steps = "1. Preheat oven to 425°F. Butter and flour ramekins.\n2. Melt chocolate and butter together.\n3. Whisk eggs, sugar, and vanilla until thick.\n4. Fold in chocolate mixture and flour.\n5. Pour into ramekins, bake 12-14 minutes.\n6. Invert onto plates, dust with powdered sugar.", AverageRating = 4.9, RatingCount = 30 },
        new Recipe { Id = 6, Title = "Caesar Salad", Category = "Salads", Ingredients = "Romaine lettuce\nParmesan cheese\nCroutons\nCaesar dressing\nLemon juice\nGarlic\nAnchovy paste\nOlive oil", Steps = "1. Wash and chop romaine lettuce.\n2. Make dressing: whisk garlic, anchovy paste, lemon juice, and olive oil.\n3. Toss lettuce with dressing.\n4. Top with shaved Parmesan and croutons.\n5. Serve immediately.", AverageRating = 4.0, RatingCount = 6 },
    };

    private readonly List<RecipeCategory> _categories = new()
    {
        new RecipeCategory { Name = "Italian", Description = "Classic pasta, pizza, and Mediterranean flavors", Icon = "🍕" },
        new RecipeCategory { Name = "Indian", Description = "Rich curries, spices, and aromatic dishes", Icon = "🍛" },
        new RecipeCategory { Name = "Mexican", Description = "Bold flavors with fresh salsas and tortillas", Icon = "🌮" },
        new RecipeCategory { Name = "Asian", Description = "Stir-fries, noodles, and umami-packed meals", Icon = "🍜" },
        new RecipeCategory { Name = "Desserts", Description = "Sweet treats and indulgent baked goods", Icon = "🍰" },
        new RecipeCategory { Name = "Salads", Description = "Fresh, healthy, and vibrant bowls", Icon = "🥗" },
    };

    public List<RecipeCategory> GetCategories() => _categories;

    public List<Recipe> GetRecipesByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetRecipeById(int id) => _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRecipe(Recipe recipe)
    {
        recipe.Id = _recipes.Max(r => r.Id) + 1;
        _recipes.Add(recipe);
    }

    public void AddRating(int recipeId, int stars)
    {
        var recipe = _recipes.FirstOrDefault(r => r.Id == recipeId);
        if (recipe is null || stars < 1 || stars > 5) return;

        var totalStars = recipe.AverageRating * recipe.RatingCount + stars;
        recipe.RatingCount++;
        recipe.AverageRating = Math.Round(totalStars / recipe.RatingCount, 1);
    }
}
"}

