@page "/recipes/{CategoryName}"

@using RecipeCommunity.Services
@inject RecipeService RecipeService

<PageTitle>@CategoryName Recipes - Recipe Community</PageTitle>

<div class="container">
    <nav class="breadcrumb">
        <a href="/">Home</a> &raquo; <span>@CategoryName</span>
    </nav>

    <h1>@CategoryName Recipes</h1>

    @if (Recipes.Count == 0)
    {
        <p>No recipes found in this category.</p>
    }
    else
    {
        <div class="recipe-list">
            @foreach (var recipe in Recipes)
            {
                <a href="/recipe/@recipe.Id" class="recipe-card">
                    <h3>@recipe.Title</h3>
                    <div class="recipe-meta">
                        <span class="stars">@GetStarDisplay(recipe.AverageRating)</span>
                        <span class="rating-text">@recipe.AverageRating / 5 (@recipe.RatingCount ratings)</span>
                    </div>
                </a>
            }
        </div>
    }
</div>

@code {
    [Parameter]
    public string CategoryName { get; set; } = string.Empty;

    private List<RecipeCommunity.Models.Recipe> Recipes { get; set; } = new();

    protected override void OnParametersSet()
    {
        Recipes = RecipeService.GetRecipesByCategory(CategoryName);
    }

    private string GetStarDisplay(double rating)
    {
        var full = (int)Math.Round(rating);
        return new string('★', full) + new string('☆', 5 - full);
    }
}

@page "/recipe/{RecipeId:int}"

@using RecipeCommunity.Services
@using RecipeCommunity.Components.Shared
@inject RecipeService RecipeService

<PageTitle>@(Recipe?.Title ?? "Recipe") - Recipe Community</PageTitle>

<div class="container">
    @if (Recipe is null)
    {
        <p>Recipe not found.</p>
    }
    else
    {
        <nav class="breadcrumb">
            <a href="/">Home</a> &raquo; <a href="/recipes/@Recipe.Category.ToLower()">@Recipe.Category</a> &raquo; <span>@Recipe.Title</span>
        </nav>

        <article class="recipe-detail">
            <h1>@Recipe.Title</h1>

            <StarRating RecipeId="Recipe.Id" CurrentRating="Recipe.AverageRating" RatingCount="Recipe.RatingCount" />

            <section class="ingredients">
                <h2>🧾 Ingredients</h2>
                <ul>
                    @foreach (var ingredient in Recipe.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries))
                    {
                        <li>@ingredient</li>
                    }
                </ul>
            </section>

            <section class="steps">
                <h2>👨‍🍳 Instructions</h2>
                @foreach (var step in Recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
                {
                    <p>@step</p>
                }
            </section>
        </article>
    }
</div>

@code {
    [Parameter]
    public int RecipeId { get; set; }

    private RecipeCommunity.Models.Recipe? Recipe { get; set; }

    protected override void OnParametersSet()
    {
        Recipe = RecipeService.GetRecipeById(RecipeId);
    }
}

@rendermode InteractiveServer

@using RecipeCommunity.Services
@inject RecipeService RecipeService

<div class="star-rating-widget">
    <span class="rating-display">@CurrentRating / 5 (@RatingCount ratings)</span>
    <div class="stars-interactive">
        @for (int i = 1; i <= 5; i++)
        {
            var star = i;
            <button class="star-btn @(star <= _hoveredStar ? "hovered" : "") @(star <= _selectedStar ? "selected" : "")"
                    @onmouseover="() => _hoveredStar = star"
                    @onmouseout="() => _hoveredStar = 0"
                    @onclick="() => SubmitRating(star)"
                    aria-label="Rate @star stars">
                @(star <= (_hoveredStar > 0 ? _hoveredStar : _selectedStar) ? "★" : "☆")
            </button>
        }
    </div>
    @if (_submitted)
    {
        <span class="rating-thanks">Thanks for rating!</span>
    }
</div>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Parameter] public double CurrentRating { get; set; }
    [Parameter] public int RatingCount { get; set; }

    private int _hoveredStar;
    private int _selectedStar;
    private bool _submitted;

    private void SubmitRating(int stars)
    {
        _selectedStar = stars;
        RecipeService.AddRating(RecipeId, stars);
        var recipe = RecipeService.GetRecipeById(RecipeId);
        if (recipe is not null)
        {
            CurrentRating = recipe.AverageRating;
            RatingCount = recipe.RatingCount;
        }
        _submitted = true;
    }
}

