toolArgs.file_text:
@page "/submit"
@rendermode InteractiveServer

@using RecipeCommunity.Models
@using RecipeCommunity.Services
@inject RecipeService RecipeService

<PageTitle>Submit a Recipe - Recipe Community</PageTitle>

<div class="container">
    <h1>📝 Submit a Recipe</h1>

    @if (_submitted)
    {
        <div class="success-message">
            <h2>✅ Recipe Submitted!</h2>
            <p>Your recipe "<strong>@_model.Title</strong>" has been added to the @_model.Category category.</p>
            <a href="/recipes/@_model.Category.ToLower()">View Category</a>
        </div>
    }
    else
    {
        <EditForm Model="_model" OnValidSubmit="HandleSubmit" FormName="recipeForm">
            <DataAnnotationsValidator />
            <ValidationSummary />

            <div class="form-group">
                <label for="title">Recipe Title</label>
                <InputText id="title" @bind-Value="_model.Title" placeholder="e.g., Grandma's Apple Pie" />
            </div>

            <div class="form-group">
                <label for="category">Category</label>
                <InputSelect id="category" @bind-Value="_model.Category">
                    <option value="">-- Select a category --</option>
                    @foreach (var cat in RecipeService.GetCategories())
                    {
                        <option value="@cat.Name">@cat.Name</option>
                    }
                </InputSelect>
            </div>

            <div class="form-group">
                <label for="ingredients">Ingredients (one per line)</label>
                <InputTextArea id="ingredients" @bind-Value="_model.Ingredients" rows="6" placeholder="2 cups flour&#10;1 cup sugar&#10;3 large apples..." />
            </div>

            <div class="form-group">
                <label for="steps">Steps (one per line)</label>
                <InputTextArea id="steps" @bind-Value="_model.Steps" rows="8" placeholder="1. Preheat oven to 350°F.&#10;2. Mix dry ingredients...&#10;3. ..." />
            </div>

            <button type="submit" class="btn-submit">Submit Recipe</button>
        </EditForm>
    }
</div>

@code {
    private Recipe _model = new();
    private bool _submitted;

    private void HandleSubmit()
    {
        if (string.IsNullOrWhiteSpace(_model.Title) || string.IsNullOrWhiteSpace(_model.Category))
            return;

        RecipeService.AddRecipe(_model);
        _submitted = true;
    }
}

